function validate([price, k]) {
  if (!Array.isArray(price) || price.length < 2 || price.length > 100000) return 'price needs 2 to 10^5 values.';
  if (price.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each price is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 2 || k > price.length) return 'k is between 2 and price.length.';
  return null;
}

