function maximumTastiness(price, k) {
  price.sort((a, b) => a - b);
  let low = 0;
  let high = price[price.length - 1] - price[0];
  while (low < high) {
    const mid = Math.floor((low + high + 1) / 2);
    let taken = 1;
    let last = price[0];
    for (let i = 1; i < price.length; i++) {
      if (price[i] - last >= mid) {
        taken++;
        last = price[i];
      }
    }
    if (taken >= k) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

