function maximumTastiness(price, k) {
  // Try every basket of k indices and measure its smallest pairwise gap.
  let result = 0;
  const chosen = [];
  const visit = (start) => {
    if (chosen.length === k) {
      let gap = Infinity;
      for (let a = 0; a < k; a++)
        for (let b = a + 1; b < k; b++) gap = Math.min(gap, Math.abs(price[chosen[a]] - price[chosen[b]]));
      result = Math.max(result, gap);
      return;
    }
    for (let i = start; i < price.length; i++) {
      chosen.push(i);
      visit(i + 1);
      chosen.pop();
    }
  };
  visit(0);
  return result;
}

